The implementation in C without preserving the coefficient vectors:
typedef struct{
	double A[n+2]; 
	double B[n+2];
	double C[n+2];
	double D[n+2];
} COEFFICIENTS;

//Apply Thomas Alg., unknowns x[1],...,x[n]
void ThomasAlg(double x[n+1], COEFFICIENTS* coeff){
	double u[n+1]={},v[n+1]={};
	double y[n+1]={},q[n+1]={};
	double* A=coeff->A, *B=coeff->B,*C=coeff->C,*D=coeff->D;
	double value=0;
	double w;
	int i;

	u[1]=gamma;
	u[n]=C[n];

	v[1]=1;
	v[n]=A[1]/gamma;

	//create matrix B
	A[1]=0;
	B[1]=B[1]-gamma;
	B[n]=B[n]-(C[n]*A[n])/gamma;
	C[n]=0;

	for(i=2;i<n+1;i++){
		w=A[i]/B[i-1];	
		B[i]=B[i]-w*C[i-1];
		D[i]=D[i]-w*D[i-1];
		u[i]=u[i]-w*u[i-1];
	}
	y[n]=D[n]/B[n];
	q[n]=u[n]/B[n];

	for(i=n-1;i>0;i--){
		y[i]=(D[i]-C[i]*y[i+1])/B[i];
		q[i]=(u[i]-C[i]*q[i+1])/B[i];
	}
	value=(v[1]*y[1]+v[n]*y[n])/(1+v[1]*q[1]+v[n]*q[n]);

	for(i=1;i<n+1;i++){
		x[i]=y[i]-q[i]*value;
	}
}

